<html lang="en">
<head>
<meta charset="utf-8">
<title>AI in Clinical Decision-Making - Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Crimson+Text:ital,wght@0,400;0,600;0,700;1,400&family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 2400px;
    background: #f1f5f9;
    font-family: 'Crimson Text', Georgia, 'Times New Roman', serif;
    color: #1e293b;
    -webkit-font-smoothing: antialiased;
  }

  /* ── HEADER ── */
  .header {
    background: linear-gradient(135deg, #0f1d36 0%, #1a3050 40%, #152238 100%);
    padding: 80px 100px 70px 100px;
