    top: 0; left: 0; right: 0; bottom: 0;
    background:
      radial-gradient(ellipse at 85% 20%, rgba(13,148,136,0.08) 0%, transparent 60%),
      radial-gradient(ellipse at 15% 80%, rgba(184,134,11,0.06) 0%, transparent 50%);
  }
  .header-content { position: relative; z-index: 1; }
  .venue {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 28px;
    font-weight: 400;
    color: rgba(255,255,255,0.6);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 28px;
  }
  .title {
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 88px;
    font-weight: 700;
    color: #ffffff;
    line-height: 1.15;
    margin-bottom: 16px;
    max-width: 85%;
  }
  .subtitle {
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 48px;
    font-weight: 400;
    color: #0d9488;
    line-height: 1.2;
    margin-bottom: 24px;
  }
  .oneliner {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 26px;
    font-weight: 300;
    color: rgba(255,255,255,0.75);
