  .header-accent {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 6px;
    background: linear-gradient(90deg, #0d9488 0%, #0d9488 40%, #b8860b 40%, #b8860b 70%, #dc2626 70%, #dc2626 100%);
  }

  /* ── SECTIONS ── */
  .section {
    margin: 36px 60px;
    background: #ffffff;
    border-radius: 8px;
    box-shadow: 0 2px 16px rgba(0,0,0,0.06);
    overflow: hidden;
  }
  .section-header {
    padding: 44px 70px 0 70px;
    display: flex;
    align-items: center;
    gap: 20px;
  }
  .section-number {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 20px;
    font-weight: 600;
    color: #ffffff;
