  }
  .section-number.teal { background: #0d9488; }
  .section-number.gold { background: #b8860b; }
  .section-number.red { background: #dc2626; }
  .section-number.navy { background: #1a3050; }
  .section-title {
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 52px;
    font-weight: 700;
    color: #0f1d36;
    line-height: 1.2;
  }
  .section-body {
    padding: 36px 70px 50px 70px;
  }

  /* ── TWO COLUMN ── */
  .two-col {
    display: flex;
    gap: 50px;
  }
  .two-col > * { flex: 1; }

  /* ── TEXT ── */
  .body-text {
    font-size: 27px;
    line-height: 1.65;
    color: #334155;
  }
  .body-text p { margin-bottom: 18px; }
  .body-text strong { color: #0f1d36; }

  /* ── STAT CARDS ── */
  .stat-row {
    display: flex;
    gap: 36px;
    margin-top: 24px;
  }
  .stat-card {
    flex: 1;
    background: #f8fafc;
    border-radius: 8px;
    padding: 36px 40px;
    text-align: center;
    border-top: 4px solid #e2e8f0;
  }
  .stat-card.teal-border { border-top-color: #0d9488; }
  .stat-card.navy-border { border-top-color: #1a3050; }
  .stat-card.gold-border { border-top-color: #b8860b; }
  .stat-value {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 64px;
    font-weight: 800;
    color: #0f1d36;
    line-height: 1.1;
  }
  .stat-value.teal { color: #0d9488; }
  .stat-value.navy { color: #1a3050; }
  .stat-value.gold { color: #b8860b; }
  .stat-label {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 20px;
    font-weight: 500;
    color: #64748b;
    margin-top: 10px;
    line-height: 1.4;
  }

  /* ── ANCHOR <5% ── */
  .anchor-section {
    margin: 36px 60px;
    background: linear-gradient(135deg, #fef2f2 0%, #fff5f5 100%);
    border-radius: 8px;
    border: 3px solid #fecaca;
    padding: 60px 80px;
    text-align: center;
  }
  .anchor-label {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 24px;
    font-weight: 600;
    color: #dc2626;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 16px;
  }
  .anchor-value {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 180px;
    font-weight: 900;
    color: #dc2626;
    line-height: 1;
    letter-spacing: -0.02em;
  }
  .anchor-desc {
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 38px;
    font-weight: 600;
    color: #7f1d1d;
    margin-top: 16px;
  }
  .anchor-sub {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 22px;
    color: #991b1b;
    margin-top: 12px;
    line-height: 1.5;
  }

  /* ── COMPARISON ── */
  .compare-row {
    display: flex;
    gap: 40px;
    margin-top: 30px;
  }
  .compare-side {
    flex: 1;
    text-align: center;
    padding: 40px 30px;
    border-radius: 8px;
  }
  .compare-side.ai {
    background: linear-gradient(135deg, #f0fdfa 0%, #e6fffa 100%);
    border: 2px solid #99f6e4;
  }
  .compare-side.clinician {
    background: #f8fafc;
    border: 2px solid #e2e8f0;
  }
  .compare-label {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 24px;
    font-weight: 600;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 16px;
  }
  .compare-value {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 100px;
    font-weight: 900;
    line-height: 1;
  }
  .compare-value.ai-val { color: #0d9488; }
  .compare-value.clin-val { color: #475569; }
  .compare-metric {
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 30px;
    color: #64748b;
    margin-top: 8px;
  }
  .compare-delta {
    text-align: center;
    margin: 0 20px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
  }
  .delta-value {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 42px;
    font-weight: 800;
    color: #0d9488;
  }
  .delta-label {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 18px;
    color: #64748b;
    margin-top: 4px;
  }

  /* ── DOMAIN TABLE ── */
  .domain-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 30px;
    font-family: 'Inter', system-ui, sans-serif;
  }
  .domain-table th {
    background: #1a3050;
    color: #ffffff;
    font-size: 22px;
    font-weight: 600;
    padding: 18px 24px;
    text-align: left;
  }
  .domain-table th:first-child { border-radius: 6px 0 0 0; }
  .domain-table th:last-child { border-radius: 0 6px 0 0; }
  .domain-table td {
    font-size: 22px;
    padding: 18px 24px;
    border-bottom: 1px solid #e2e8f0;
    color: #334155;
  }
  .domain-table tr:nth-child(even) td { background: #f8fafc; }
  .domain-table .bar-cell {
    position: relative;
  }
  .domain-bar {
    height: 8px;
    border-radius: 4px;
    margin-top: 6px;
  }
  .domain-bar.teal { background: #0d9488; }
  .domain-bar.slate { background: #94a3b8; }

  /* ── WARNING BOX ── */
  .warning-box {
    background: #fffbeb;
    border: 2px solid #fde68a;
    border-left: 8px solid #f59e0b;
    border-radius: 8px;
    padding: 40px;
    margin-bottom: 30px;
  }
  .warning-stat {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 96px;
    font-weight: 900;
    color: #b8860b;
