  .warning-label {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 22px;
    font-weight: 600;
    color: #92400e;
    margin-top: 12px;
    line-height: 1.4;
  }
  .warning-desc {
    font-size: 24px;
    color: #78350f;
    margin-top: 16px;
    line-height: 1.6;
  }

  /* ── BARRIERS ── */
  .barriers-list {
    display: flex;
    flex-wrap: wrap;
    gap: 28px;
    margin-top: 24px;
  }
  .barrier-item {
    flex: 0 0 calc(33.33% - 19px);
    background: #f8fafc;
    border-radius: 8px;
    padding: 32px;
    border-top: 4px solid #dc2626;
  }
  .barrier-item:nth-child(4), .barrier-item:nth-child(5) {
    flex: 0 0 calc(50% - 14px);
  }
  .barrier-num {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 18px;
    font-weight: 700;
    color: #dc2626;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 10px;
  }
  .barrier-title {
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 26px;
    font-weight: 700;
    color: #0f1d36;
    margin-bottom: 8px;
  }
  .barrier-desc {
    font-size: 21px;
    color: #64748b;
    line-height: 1.5;
  }

  /* ── RECOMMENDATIONS ── */
  .recs-list {
    counter-reset: rec;
    margin-top: 20px;
  }
  .rec-item {
    counter-increment: rec;
    display: flex;
    align-items: flex-start;
    gap: 24px;
    padding: 28px 0;
    border-bottom: 1px solid #e2e8f0;
  }
  .rec-item:last-child { border-bottom: none; }
  .rec-num {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 36px;
    font-weight: 800;
    color: #0d9488;
    flex-shrink: 0;
    width: 56px; height: 56px;
    border-radius: 50%;
    background: #f0fdfa;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .rec-text {
    font-size: 28px;
    line-height: 1.5;
    color: #334155;
    padding-top: 8px;
  }
  .rec-text strong { color: #0f1d36; }

  /* ── INFOGRAPHIC CONTAINERS ── */
  .infographic-container {
    width: 100%;
    margin: 20px 0;
  }
  .infographic-container canvas,
  .infographic-container svg {
    max-width: 100%;
    height: auto;
  }

  /* ── FOOTER ── */
  .footer {
    background: #0f1d36;
    padding: 50px 100px;
    color: rgba(255,255,255,0.5);
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 20px;
    line-height: 1.6;
  }

  /* ── DOMAIN CHART BARS ── */
  .domain-chart { margin-top: 30px; }
  .domain-row {
