  .domain-name {
    width: 220px;
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 22px;
    font-weight: 500;
    color: #334155;
    text-align: right;
    flex-shrink: 0;
  }
  .domain-bar-wrap {
    flex: 1;
    height: 42px;
    background: #f1f5f9;
    border-radius: 6px;
    overflow: hidden;
    position: relative;
  }
  .domain-bar-fill {
    height: 100%;
    border-radius: 6px;
    display: flex;
    align-items: center;
    padding-left: 18px;
  }
  .domain-bar-fill.teal { background: linear-gradient(90deg, #0d9488, #14b8a6); }
  .domain-bar-fill.slate { background: linear-gradient(90deg, #64748b, #94a3b8); }
  .domain-bar-val {
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 24px;
    font-weight: 700;
    color: #ffffff;
