        <div style="font-family:'Inter',sans-serif;font-size:28px;color:#64748b;">+1.7 pp</div>
      </div>
      <div class="specificity-item">
        <div class="spec-label">Clinician Specificity</div>
        <div class="spec-value slate">91.4%</div>
      </div>
