      <h3 style="font-family:'Crimson Text',Georgia,serif;font-size:32px;font-weight:600;color:#0f1d36;margin-bottom:8px;">AI Sensitivity by Clinical Domain</h3>
      <div class="domain-row">
        <div class="domain-name">Ophthalmology</div>
        <div class="domain-bar-wrap"><div class="domain-bar-fill teal" style="width:90.1%"><span class="domain-bar-val">90.1%</span></div></div>
      </div>
      <div class="domain-row">
        <div class="domain-name">Radiology</div>
        <div class="domain-bar-wrap"><div class="domain-bar-fill teal" style="width:89.3%"><span class="domain-bar-val">89.3%</span></div></div>
      </div>
      <div class="domain-row">
        <div class="domain-name">Dermatology</div>
        <div class="domain-bar-wrap"><div class="domain-bar-fill teal" style="width:86.7%"><span class="domain-bar-val">86.7%</span></div></div>
      </div>
