const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Set viewport to poster width
  await page.setViewportSize({ width: 2400, height: 1200 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait for Infographic renders to complete (or timeout after 15s)
  try {
    await page.waitForFunction(() => {
      return document.body.getAttribute('data-renders-complete') === 'true';
    }, { timeout: 15000 });
  } catch (e) {
    console.log('Infographic render wait timed out, proceeding anyway...');
  }

  // Extra settle time for fonts and layout
  await page.waitForTimeout(3000);

  // Get full page height
  const bodyHandle = await page.$('body');
  const boundingBox = await bodyHandle.boundingBox();
  const fullHeight = Math.ceil(boundingBox.height);
  console.log(`Full page height: ${fullHeight}px`);

  // Set viewport to full height for clean screenshot
  await page.setViewportSize({ width: 2400, height: fullHeight });

  // Take full-page screenshot at 2x for crisp output
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    deviceScaleFactor: 2,
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();

