const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Use a wide viewport to let the poster render fully
  await page.setViewportSize({ width: 2600, height: 1200 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts to load
  await page.waitForTimeout(4000);

  // Measure the full page content size
  const bodyHandle = await page.$('body');
  const boundingBox = await bodyHandle.boundingBox();
  const fullHeight = Math.ceil(boundingBox.height);
  const fullWidth = Math.ceil(boundingBox.width);
  console.log(`Content size: ${fullWidth}x${fullHeight}px`);

  // Set viewport to exact content dimensions
