const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Set initial viewport wide enough
  await page.setViewportSize({ width: 2600, height: 1200 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait for fonts
  await page.waitForTimeout(4000);

  // Measure original content size
  const bodyHandle = await page.$('body');
  const boundingBox = await bodyHandle.boundingBox();
  const origW = Math.ceil(boundingBox.width);
  const origH = Math.ceil(boundingBox.height);
  console.log(`Original content size: ${origW}x${origH}px`);

  // Apply 2x scale transform to body and set viewport to match doubled size
  const scale = 2;
  await page.addStyleTag({
    content: `body { transform: scale(${scale}); transform-origin: top left; }`
  });

  const scaledW = origW * scale;
  const scaledH = origH * scale;
  await page.setViewportSize({ width: scaledW, height: scaledH });

  await page.waitForTimeout(500);

  await page.screenshot({
    path: '/app/output/final_poster.png',
  });

  console.log(`Poster saved: ${scaledW}x${scaledH}px`);
  await browser.close();
})();

